def entry_link(language='ru'):
    index = ('ru', 'en', 'de', 'es').index(language)
    page = 'community.html' if language == 'ru' else 'community.'+language+'.html'
    return '<p id="collaboration-link" data-i18n-fixed><a href="'+page+'">'+html.escape(COPY['entry'][index])+'</a></p>'


def render(root, language='ru'):
    index = ('ru', 'en', 'de', 'es').index(language)
    text = lambda name: html.escape(COPY[name][index], quote=True)
    page = lambda name: name+'.html' if language == 'ru' else name+'.'+language+'.html'
    snapshot = json.loads((root/'data/community-discussions.json').read_text())
    e = lambda value: html.escape(str(value), quote=True)
    def date(value):
        return datetime.fromisoformat(value.replace('Z','+00:00')).astimezone(ZoneInfo('Europe/Berlin')).strftime('%Y-%m-%d %H:%M %Z')
    channels = [('molt', 'molt_status', snapshot['source_url']),
        ('a2a', 'a2a_status', 'https://github.com/a2aproject/A2A/discussions/2406'),
        ('claw', 'claw_status', 'https://github.com/eliswedtlv/ClawMesh/issues/1')]
    platforms = ''.join(f'<article class="collab-channel"><h3>{text(name)}</h3><p>{text(status)}</p><a href="{e(url)}" rel="noopener noreferrer">{text("open")}</a></article>' for name,status,url in channels)
    entries = []
    identifiers = {row['id'] for row in snapshot['comments']}
    for row in snapshot['comments']:
        parent = row['parent_id']
        reply = f'<p class="small">{text("parent")} <a href="#comment-{e(parent)}">{e(parent[:8])}</a></p>' if parent in identifiers else ''
        mode = 'our' if row['project_account'] else 'external'
        entries.append(f'<details class="collab-message" id="comment-{e(row["id"])}"><summary><span>{e(row["claimed_author"])}</span> <span>{text(mode)}</span> <time datetime="{e(row["created_at"])}">{e(date(row["created_at"]))}</time></summary>{reply}<div class="collab-message-text" lang="en">{e(row["text"])}</div><p class="small">Moltbook · {e(row["id"])}</p></details>')
    steps = ''.join('<li>'+e(s)+'</li>' for s in COPY['steps'][index])
    return f'''<div id="collaboration-hub" data-i18n-fixed>
<section class="section"><h1>{text('title')}</h1><p class="lead">{text('lead')}</p><p><strong>{text('finding')}</strong></p><p>{text('why')}</p><nav class="collab-jumps" aria-label="{text('paths')}"><a href="#research-links">{html.escape(RESEARCH_COPY['title'][index])}</a><a href="#channels">{text('platforms')}</a><a href="#external-discussion">{text('messages')}</a><a href="#contribute">{text('where')}</a><a href="#liaison">{text('agent')}</a></nav></section>
<section class="section" id="channels"><h2>{text('platforms')}</h2><div class="collab-channels">{platforms}</div></section>
<section class="section" id="external-discussion" data-project-label="{text('our')}" data-external-label="{text('external')}" data-parent-label="{text('parent')}" data-loading="{text('loading')}" data-error="{text('error')}"><div class="section-intro"><h2>{text('messages')}</h2><div><p>{text('snapshot')} <time id="discussion-observed" datetime="{e(snapshot['observed_at'])}">{e(date(snapshot['observed_at']))}</time>.</p><p>{text('count')}: <span id="discussion-count">{len(entries)}</span>. <a href="{e(snapshot['source_url'])}">{text('open')}</a> · <a href="data/community-discussions.json">{text('record')}</a></p><p class="small">{text('reported')}: <span id="discussion-source-count">{e(snapshot['reported_comment_count'])}</span> · {text('returned')}: <span id="discussion-returned-count">{e(snapshot['returned_comment_count'])}</span> · {text('accounts')}: <span id="discussion-account-count">{len(snapshot['external_accounts'])}</span></p><button class="button secondary" type="button" id="discussion-refresh">{text('refresh')}</button><p role="status" aria-live="polite" id="discussion-refresh-status"></p></div></div><p>{text('limit')}</p><div class="collab-messages" id="discussion-messages">{''.join(entries)}</div></section>
<section class="section" id="contribute"><h2>{text('where')}</h2><div class="collab-channels"><article><h3>{text('rfc')}</h3><p>{text('rfc_help')}</p><a href="{page('rfcs')}">{text('all_rfc')}</a></article><article><h3>{text('general')}</h3><p>{text('general_help')}</p><a href="{page('participate')}#join-form">{text('proposal')}</a></article><article><h3>{text('private')}</h3><p>{text('private_help')}</p><a href="{page('agents')}#a2a-guide">{text('guide')}</a></article></div></section>
<section class="section" id="process"><h2>{text('process')}</h2><ol class="collab-process">{steps}</ol><h3>{text('candidate')}</h3><p>{text('candidate_help')}</p><a href="https://github.com/relcom-technologies/ipvx-research/tree/04f4104bc0fdba80723eb76d390fdb8a4d6a1bd5/experiments/a2a-interop">IPVX-A2A-INTEROP-001 · v1.0-rc1</a></section>
<section class="section" id="liaison"><h2>{text('agent')}</h2><p>{text('agent_help')}</p><p id="liaison-runtime-status" data-ready="{text('runtime_ready')}" data-observing="{text('runtime_observing')}" data-error="{text('runtime_error')}">{text('agent_pending')}</p><p id="liaison-runtime-meta" class="small" data-time="{text('runtime_time')}" data-reserved="{text('runtime_reserved')}"></p><a href="data/liaison-status.json">IPvXResearchLiaison · JSON</a></section></div>'''
